// 09 - Speed-up: the same work on one core, then on every core.
// One suite, one file: it registers itself with the runner; there is no
// list of suites to keep in step with the files.
// GENERATED by micro-os-scaffold (--micro-test-plus).
#include <mtp_board.hpp>
#include "smp_helpers.hpp"

using namespace os::rtos;
using namespace mtp_smp;

namespace
{
  // One unit of work: `iterations` steps of a 32-bit LCG and a rotate,
  // kept in registers. Returns the final value, so it cannot be folded away.
  std::uint32_t
  work_unit (std::uint32_t iterations)
  {
    std::uint32_t x = 12345u;
    std::uint32_t y = 0x9e3779b9u;
    for (std::uint32_t i = 0; i < iterations; ++i)
      {
        x = x * 1664525u + 1013904223u;
        y ^= (x >> 7) | (x << 25);
        asm volatile ("" : "+r"(x), "+r"(y));
      }
    return x ^ y;
  }

  struct speed_job
  {
    std::uint32_t iterations;
    unsigned units;
    std::uint32_t result; // the last unit's result
  };

  speed_job g_jobs[ncpu];

  void*
  run_job (void* arg)
  {
    auto* job = static_cast<speed_job*> (arg);
    std::uint32_t r = 0;
    for (unsigned u = 0; u < job->units; ++u)
      {
        r = work_unit (job->iterations);
      }
    job->result = r;
    return nullptr;
  }

  unsigned
  to_ms (clock::duration_t ticks)
  {
    return static_cast<unsigned> ((static_cast<std::uint64_t> (ticks) * 1000u)
                                  / clock_systick::frequency_hz);
  }
} // namespace

mt::static_suite suite_speedup{
  "09 - Speed-up", mtp_board::runner (),
  [] (mt::suite& ts) {
    ts.test ("the same work, one core then every core", [] (auto& t) {
      // Calibrate a unit of at least 100 ms on one core.
      std::uint32_t iterations = 1u << 16;
      while (true)
        {
          const auto begin = sysclock.now ();
          (void)work_unit (iterations);
          if (sysclock.now () - begin >= ms (100) || iterations >= (1u << 30))
            {
              break;
            }
          iterations *= 2;
        }

      // One core does OS_NCPU units.
      g_jobs[0] = { iterations, ncpu, 0 };
      auto begin = sysclock.now ();
      finish (spawn ("mtp-speed-1", run_job, &g_jobs[0], static_cast<int> (last)));
      const auto one_core = sysclock.now () - begin;
      const std::uint32_t expected = g_jobs[0].result;

      // Every core does one unit, at the same time.
      thread* threads[ncpu] = {};
      begin = sysclock.now ();
      for (unsigned core = 0; core < ncpu; ++core)
        {
          g_jobs[core] = { iterations, 1, 0 };
          threads[core] = spawn ("mtp-speed-n", run_job, &g_jobs[core],
                                 static_cast<int> (core));
        }
      for (auto* th : threads)
        {
          finish (th);
        }
      const auto all_cores = sysclock.now () - begin;

      bool same = true;
      for (unsigned core = 0; core < ncpu; ++core)
        {
          same = same && g_jobs[core].result == expected;
        }
      const unsigned speedup_x100 = static_cast<unsigned> (
          all_cores == 0 ? 0u : (static_cast<std::uint64_t> (one_core) * 100u) / all_cores);

      static char what[160];
      std::snprintf (what, sizeof (what),
                     "speed-up %u.%02ux on %u cores (1 core %u ms, %u cores %u ms)",
                     speedup_x100 / 100, speedup_x100 % 100, ncpu, to_ms (one_core),
                     ncpu, to_ms (all_cores));
      std::printf ("# %s\n", what);

      t.expect (same) << "every core computed the same result";
#if defined(QEMU_BUILD)
      t.expect (mt::gt (speedup_x100, 0u)) << what;
#else
      t.expect (mt::ge (speedup_x100, 80u * ncpu)) << what;
#endif
    });
  }
};
